import{_ as i,a8 as e,o as r,c as o,ah as s,K as a}from"./chunks/framework.DX2Vcg1x.js";import"./chunks/theme.BzIrHAwa.js";const m=JSON.parse('{"title":"上限分析（Ceiling Analysis）","description":"","frontmatter":{"title":"上限分析（Ceiling Analysis）","abstract":"上限分析方法讲解，一种系统性错误分析手段，通过逐模块人工补全来确定机器学习流水线中最具改进价值的环节。","created":"2026-07-10T00:00:00.000Z","tags":["机器学习","方法论"],"type":"概念解释","category":["🤖 AI大模型","机器学习"]},"headers":[],"relativePath":"vault/Knowledge/AI/上限分析.md","filePath":"vault/Knowledge/AI/上限分析.md","lastUpdated":1790655645000}'),d={name:"vault/Knowledge/AI/上限分析.md"};function c(h,t,_,g,p,b){const l=e("NolebaseGitContributors"),n=e("NolebaseGitChangelog");return r(),o("div",null,[t[0]||(t[0]=s('<h1 id="上限分析-ceiling-analysis" tabindex="-1">上限分析（Ceiling Analysis） <a class="header-anchor" href="#上限分析-ceiling-analysis" aria-label="Permalink to “上限分析（Ceiling Analysis）”">​</a></h1><p>上限分析是一种系统性的错误分析方法，用于确定 ML 流水线中哪个模块最具改进价值。</p><h2 id="核心思路" tabindex="-1">核心思路 <a class="header-anchor" href="#核心思路" aria-label="Permalink to “核心思路”">​</a></h2><p>逐一将流水线中某个模块替换为&quot;完美&quot;输出（如人工标注），观察整体精度提升幅度。提升最大的模块就是<strong>最佳投入方向</strong>。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>假设一个 OCR 流水线：文字检测 → 字符分割 → 字符识别。通过手工给出某模块的完美结果，对比系统性提升：</p><table tabindex="0"><thead><tr><th>替换的模块</th><th style="text-align:center;">整体精度提升</th><th style="text-align:center;">优先级</th></tr></thead><tbody><tr><td>文字检测 → 完美</td><td style="text-align:center;">+15%</td><td style="text-align:center;">高</td></tr><tr><td>字符分割 → 完美</td><td style="text-align:center;">+6%</td><td style="text-align:center;">中</td></tr><tr><td>字符识别 → 完美</td><td style="text-align:center;">+3%</td><td style="text-align:center;">低</td></tr></tbody></table><p>此时优先投入精力到文字检测。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>上限分析回答&quot;要改善哪里&quot;，不是&quot;如何改善&quot;</li><li>适用于多模块串联流水线</li><li>手工标注成本高，选代表性样本即可</li><li>与 Ablation Study（消融实验&quot;去掉某个模块的表现&quot;）形成互补视角</li></ul>',10)),a(l),a(n)])}const x=i(d,[["render",c]]);export{m as __pageData,x as default};
